torch.manual_seed(5); M=2048
xi0=torch.randn(M,2)
def modecenters(a,init):
    th=np.radians(angs(a)); cen=np.radians(init.copy())
    for _ in range(20):
        d=np.angle(np.exp(1j*(th[:,None]-cen[None,:]))); lab=np.abs(d).argmin(1)
        for j in range(8):
            m=lab==j
            if m.any(): cen[j]=cen[j]+np.angle(np.exp(1j*d[m,j]).mean())
    return np.degrees(cen)%360, lab
