import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c2_out_act_k16.npy')); b0=-16.6759
d=np.load('dec1.npz'); xi=torch.tensor(d['xi']); c=torch.tensor(d['c']); a0=d['a']
def tgt(a,c):
    ang=np.degrees(np.arctan2(a[:,1],a[:,0])); cen=-124+58*c
    return (np.abs(ang-cen)<12)&(np.linalg.norm(a,axis=1)>2)
T0=tgt(a0,d['c']); print('base target',T0.mean())
R=torch.tensor([[0.,-1.],[1.,0.]])
@torch.no_grad()
def dec(thr,klo,khi,s):
    x=xi.clone(); fired=torch.zeros(len(x),dtype=torch.bool)
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,A=net.velocity(x,t,c,("out_act",),count=False)
        f=(A['out_act']@w+b0>thr)&(k>=klo)&(k<khi)
        fired|=f
        v=v+f[:,None].float()*(s*(x@R.T))
        x=x-v/20
    return x.numpy(),fired.numpy()
